export const CONSOLE_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n<meta name=\"robots\" content=\"noindex,nofollow\" />\n<title>FL3SH Console</title>\n<style>\n  :root{color-scheme:dark;--bg:#080810;--panel:rgba(22,20,40,.72);--border:rgba(139,92,246,.24);\n    --accent:#8b5cf6;--accent2:#c4b5fd;--text:#ecebf6;--muted:#9b98b4;--dim:#6f6b88;\n    --danger:#f87171;--ok:#4ade80;--warn:#fbbf24}\n  *{box-sizing:border-box}\n  body{margin:0;min-height:100vh;font-family:Inter,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n    color:var(--text);background:radial-gradient(1100px 620px at 12% -10%,rgba(139,92,246,.16),transparent 58%),\n    radial-gradient(800px 500px at 100% 0%,rgba(59,130,246,.09),transparent 55%),var(--bg)}\n  .wrap{max-width:1160px;margin:0 auto;padding:28px 22px 60px}\n  header{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-bottom:22px}\n  .logo{width:48px;height:48px;border-radius:15px;display:grid;place-items:center;\n    background:linear-gradient(145deg,#8b5cf6,#5b21b6);box-shadow:0 0 28px rgba(139,92,246,.42)}\n  h1{margin:0;font-size:24px;font-weight:800;letter-spacing:.2px;\n    background:linear-gradient(90deg,#c4b5fd,#fff);-webkit-background-clip:text;background-clip:text;color:transparent}\n  .tag{font-size:9px;font-weight:800;letter-spacing:1px;padding:4px 8px;border-radius:99px;color:#ddd6fe;\n    background:rgba(139,92,246,.16);border:1px solid var(--border)}\n  .who{font-size:11px;color:var(--muted);margin-top:3px}\n  .head-actions{margin-left:auto;display:flex;gap:8px;flex-wrap:wrap}\n  button{gap:6px;display:inline-flex;align-items:center;justify-content:center;border:1px solid var(--border);\n    background:rgba(255,255,255,.05);color:var(--text);border-radius:10px;padding:8px 12px;font-size:12px;\n    cursor:pointer;transition:.15s}\n  button:hover:not(:disabled){background:rgba(139,92,246,.18);border-color:var(--accent)}\n  button:disabled{opacity:.5;cursor:default}\n  button.primary{background:linear-gradient(135deg,#8b5cf6,#6d28d9);border-color:transparent;font-weight:700}\n  button.danger{color:var(--danger);border-color:rgba(248,113,113,.3)}\n  button.ok{color:var(--ok);border-color:rgba(74,222,128,.3)}\n  button.sm{padding:5px 9px;font-size:11px;border-radius:8px}\n  .stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:18px}\n  .stat{padding:15px 17px;border-radius:16px;background:var(--panel);border:1px solid var(--border)}\n  .stat b{display:block;font-size:25px;line-height:1.1}\n  .stat span{font-size:11px;color:var(--muted)}\n  .grid{display:grid;grid-template-columns:1.25fr .9fr;gap:14px;align-items:start}\n  .card{padding:18px;border-radius:18px;background:var(--panel);border:1px solid var(--border);margin-bottom:14px}\n  .card h2{margin:0 0 4px;font-size:14px;display:flex;align-items:center;gap:8px}\n  .hint{font-size:10.5px;color:var(--dim);margin:0 0 13px}\n  label{display:block;font-size:11px;color:var(--muted);margin:11px 0 5px}\n  input,select,textarea{width:100%;padding:10px 11px;border-radius:10px;color:var(--text);font-size:12.5px;\n    background:rgba(255,255,255,.045);border:1px solid var(--border);outline:none;font-family:inherit}\n  input:focus,select:focus,textarea:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(139,92,246,.13)}\n  textarea{min-height:70px;resize:vertical}\n  .row{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n  .item{padding:12px;border-radius:12px;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.06);margin-bottom:9px}\n  .item .top{display:flex;align-items:center;gap:7px;flex-wrap:wrap}\n  .item .top strong{font-size:12.5px}\n  .item .top .pill{margin-left:auto;font-size:9.5px;padding:3px 7px;border-radius:99px;text-transform:uppercase;\n    letter-spacing:.5px;font-weight:800;background:rgba(139,92,246,.17);color:var(--accent2)}\n  .item .pill.pending{background:rgba(248,113,113,.16);color:var(--danger)}\n  .item .pill.ok{background:rgba(74,222,128,.14);color:var(--ok)}\n  .item p{margin:7px 0 0;font-size:11.5px;color:var(--muted);line-height:1.5;word-break:break-word}\n  .item .meta{font-size:10px;color:var(--dim);margin-top:5px}\n  .item .acts{display:flex;gap:6px;margin-top:9px;flex-wrap:wrap}\n  .empty{font-size:11.5px;color:var(--dim);padding:8px 0}\n  .user{width:100%;justify-content:space-between;text-align:left;padding:9px 10px;margin-bottom:6px;font-size:11.5px}\n  .user small{color:var(--dim);font-size:10px}\n  #toast{position:fixed;right:20px;bottom:20px;z-index:50;max-width:360px;padding:13px 16px;border-radius:12px;\n    font-size:12.5px;font-weight:600;background:rgba(20,18,38,.96);border:1px solid var(--border);\n    box-shadow:0 18px 50px rgba(0,0,0,.6);opacity:0;transform:translateY(14px);pointer-events:none;transition:.22s}\n  #toast.show{opacity:1;transform:none}\n  #toast.ok{border-color:rgba(74,222,128,.5)}#toast.err{border-color:rgba(248,113,113,.5)}\n  .switch{display:flex;align-items:center;gap:7px;font-size:11px;color:var(--muted);cursor:pointer}\n  .foot{text-align:center;font-size:10px;color:var(--dim);margin-top:26px}\n  @media(max-width:820px){.grid{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header>\n    <div class=\"logo\">\n      <svg width=\"26\" height=\"26\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"1.7\" stroke-linecap=\"round\">\n        <rect x=\"4\" y=\"8\" width=\"16\" height=\"12\" rx=\"3\"/><path d=\"M12 8V5\"/><circle cx=\"12\" cy=\"3.5\" r=\"1.4\" fill=\"#fff\"/>\n        <circle cx=\"9\" cy=\"14\" r=\"1\"/><circle cx=\"15\" cy=\"14\" r=\"1\"/><path d=\"M9 17.5h6\"/>\n      </svg>\n    </div>\n    <div><h1>FL3SH Console</h1><div class=\"who\" id=\"who\">Private owner controls</div></div>\n    <span class=\"tag\">PRIVATE</span>\n    <div class=\"head-actions\">\n      <button id=\"notif\" class=\"sm\" type=\"button\">🔔 Alerts off</button>\n      <button id=\"refresh\" class=\"sm\" type=\"button\">↻ Refresh</button>\n      <button id=\"logout\" class=\"sm\" type=\"button\">Sign out</button>\n    </div>\n  </header>\n\n  <div class=\"stats\">\n    <div class=\"stat\"><b id=\"s-alerts\" style=\"color:var(--danger)\">0</b><span>AI alerts awaiting you</span></div>\n    <div class=\"stat\"><b id=\"s-active\" style=\"color:var(--warn)\">0</b><span>Active restrictions</span></div>\n    <div class=\"stat\"><b id=\"s-users\" style=\"color:var(--accent2)\">0</b><span>Registered accounts</span></div>\n  </div>\n\n  <div id=\"app\"></div>\n  <div class=\"foot\">MADE BY FL3SH · r00ster · Private console</div>\n</div>\n<div id=\"toast\"></div>\n\n<script>\nconst $ = (s) => document.querySelector(s)\nconst state = { data:null, busy:false, first:true, seen:new Set(JSON.parse(localStorage.getItem('fl3sh.seen')||'[]')) }\nlet toastTimer\n\nfunction esc(s){return String(s==null?'':s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]))}\nfunction when(ts){if(!ts)return 'never';return new Date(ts).toLocaleString([],{dateStyle:'medium',timeStyle:'short'})}\nfunction toast(msg,type=''){\n  const t=$('#toast');t.textContent=msg;t.className='show '+type;clearTimeout(toastTimer)\n  toastTimer=setTimeout(()=>t.className='',3800)\n}\nasync function api(path,opts={}){\n  const res=await fetch(path,{credentials:'same-origin',...opts,headers:{'Content-Type':'application/json',...(opts.headers||{})}})\n  let data={};try{data=await res.json()}catch{}\n  if(res.status===401||res.status===403){location.reload();throw new Error('Session ended.')}\n  if(!res.ok)throw new Error(data.error||'Request failed ('+res.status+')')\n  return data\n}\n\nfunction alertsHTML(list,mods){\n  if(!list.length)return '<div class=\"empty\">No new alerts. NEXUS is on watch.</div>'\n  return list.map(a=>{\n    const mod=(mods||[]).find(m=>m.id===a.moderation_id)\n    const ipBtn=mod&&mod.ip_hash\n      ? `<button class=\"danger sm\" data-act=\"escalate-ip\" data-id=\"${esc(mod.id)}\" data-target=\"${esc(mod.ip_hash.slice(0,16))}\">Ban this IP</button>` : ''\n    return `<div class=\"item\">\n    <div class=\"top\"><strong>⚠ ${esc(a.title)}</strong><span class=\"pill pending\">awaiting</span></div>\n    <p>${esc(a.detail)}</p>\n    <div class=\"meta\">${when(a.created_at)}${mod&&mod.ip_display?' · IP '+esc(mod.ip_display):''}</div>\n    <div class=\"acts\">\n      <button class=\"ok sm\" data-act=\"decision\" data-id=\"${esc(a.id)}\" data-value=\"accept\">✓ Accept — keep restriction</button>\n      <button class=\"sm\" data-act=\"decision\" data-id=\"${esc(a.id)}\" data-value=\"decline\">✕ Decline — release</button>\n      ${ipBtn}\n    </div></div>`}).join('')\n}\nfunction modsHTML(list){\n  if(!list.length)return '<div class=\"empty\">No active restrictions.</div>'\n  const label={soft_ban:'Soft ban',ban:'Ban',ip_ban:'IP ban',timeout:'Timeout'}\n  return list.map(m=>{\n    const done=m.status==='pending'\n    const opts=Object.entries(label).map(([v,l])=>`<option value=\"${v}\" ${m.type===v?'selected':''}>${l}</option>`).join('')\n    const verifyTarget=m.type==='ip_ban'&&m.ip_hash?m.ip_hash.slice(0,16):(m.target_email||m.id)\n    const ipInfo=m.ip_display?`<div class=\"meta\">IP ${esc(m.ip_display)}${m.ip_hash?' · hash '+esc(m.ip_hash.slice(0,12))+'…':''}</div>`:''\n    const ipBtn=m.type!=='ip_ban'&&m.ip_hash\n      ? `<button class=\"danger sm\" data-act=\"escalate-ip\" data-id=\"${esc(m.id)}\" data-target=\"${esc(m.ip_hash.slice(0,16))}\">Switch to IP ban</button>` : ''\n    const hours=m.expires_at?Math.max(1,Math.round((m.expires_at-Date.now())/3600000)):24\n    return `<div class=\"item\">\n      <div class=\"top\"><strong>${esc(label[m.type]||m.type)}</strong><span class=\"pill ${done?'pending':''}\">${esc(m.status)}</span></div>\n      <p>${esc(m.target_email||m.ip_display||'Unknown target')} — ${esc(m.reason)}</p>\n      ${ipInfo}\n      <div class=\"meta\">By ${esc(m.created_by)} · ${m.expires_at?'until '+when(m.expires_at):'no expiry'}</div>\n      <div class=\"row\" style=\"margin-top:9px\">\n        <div><label>Change type</label><select class=\"mtype\" data-id=\"${esc(m.id)}\">${opts}</select></div>\n        <div><label>Reason (required)</label><input class=\"mreason\" data-id=\"${esc(m.id)}\" value=\"${esc(m.reason)}\" /></div>\n      </div>\n      <div class=\"row\" style=\"margin-top:7px\">\n        <div><label>Hours — timeout only</label><input class=\"mhours\" data-id=\"${esc(m.id)}\" type=\"number\" min=\"1\" max=\"720\" value=\"${hours}\" /></div>\n        <div style=\"display:flex;align-items:flex-end\"><button class=\"primary sm\" data-act=\"update\" data-id=\"${esc(m.id)}\" style=\"width:100%\">Keep as this type</button></div>\n      </div>\n      <div class=\"acts\">\n        <button class=\"sm\" data-act=\"verify\" data-target=\"${esc(verifyTarget)}\">Verify enforced</button>\n        ${ipBtn}\n        <button class=\"danger sm\" data-act=\"revoke\" data-id=\"${esc(m.id)}\">Revoke</button>\n      </div></div>`}).join('')\n}\nfunction usersHTML(list){\n  if(!list.length)return '<div class=\"empty\">No accounts yet.</div>'\n  return list.map(u=>`<button class=\"user\" data-act=\"target\" data-email=\"${esc(u.email)}\">\n    <span>${esc(u.email)}</span><small>${u.conversations} chats · ${when(u.created_at)}</small></button>`).join('')\n}\nfunction historyHTML(alerts,mods){\n  const a=alerts.filter(x=>x.status!=='pending').slice(0,6).map(x=>`<div class=\"meta\">${esc(x.title)} → ${esc(x.status)}</div>`).join('')\n  const m=mods.filter(x=>x.status==='revoked').slice(0,6).map(x=>`<div class=\"meta\">${esc(x.target_email||x.ip_display||'IP')} → revoked</div>`).join('')\n  return (a||m)?(a+m):'<div class=\"empty\">Nothing reviewed yet.</div>'\n}\n\nfunction render(){\n  const d=state.data;if(!d)return\n  const pending=d.alerts.filter(a=>a.status==='pending')\n  const active=d.moderations.filter(m=>m.status==='active'||m.status==='pending')\n  $('#who').textContent='Signed in as '+d.owner.email\n  $('#s-alerts').textContent=pending.length\n  $('#s-active').textContent=active.length\n  $('#s-users').textContent=d.users.length\n  $('#app').innerHTML=`\n  <div class=\"grid\">\n    <div>\n      <section class=\"card\"><h2>📬 AI alerts</h2><p class=\"hint\">When NEXUS blocks a request, you decide whether the hold stays. You can keep it as-is or switch it to a timeout, ban, or IP ban.</p>${alertsHTML(pending,d.moderations)}</section>\n      <section class=\"card\"><h2>🛡 Active restrictions</h2><p class=\"hint\">${active.length} enforced right now. Verify checks the live server state.</p>${modsHTML(active)}</section>\n      <section class=\"card\"><h2>🕘 History</h2><p class=\"hint\">Recently reviewed alerts and revoked actions.</p>${historyHTML(d.alerts,d.moderations)}</section>\n    </div>\n    <div>\n      <section class=\"card\">\n        <h2>⚡ New moderation</h2><p class=\"hint\">A reason is always required and stored.</p>\n        <form id=\"modform\">\n          <label>Type</label>\n          <select name=\"type\" id=\"mtype\"><option value=\"ban\">Ban</option><option value=\"soft_ban\">Soft ban</option><option value=\"ip_ban\">IP ban</option><option value=\"timeout\">Timeout</option></select>\n          <label>Target <span id=\"tlabel\">(email or account ID)</span></label>\n          <input name=\"target\" id=\"mtarget\" list=\"userlist\" placeholder=\"member@example.com\" required />\n          <datalist id=\"userlist\">${d.users.map(u=>`<option value=\"${esc(u.email)}\"></option>`).join('')}</datalist>\n          <div id=\"hourswrap\" style=\"display:none\"><label>Hours (1–720)</label><input name=\"hours\" type=\"number\" min=\"1\" max=\"720\" value=\"24\" /></div>\n          <label>Reason (required)</label>\n          <textarea name=\"reason\" minlength=\"5\" placeholder=\"Why are you taking this action?\" required></textarea>\n          <button class=\"primary\" style=\"width:100%;margin-top:14px\" type=\"submit\" ${state.busy?'disabled':''}>Apply restriction</button>\n        </form>\n      </section>\n      <section class=\"card\"><h2>👤 Accounts</h2><p class=\"hint\">Click an account to fill the target field.</p>${usersHTML(d.users)}</section>\n    </div>\n  </div>`\n  $('#mtype').addEventListener('change',e=>{\n    $('#hourswrap').style.display=e.target.value==='timeout'?'block':'none'\n    $('#tlabel').textContent=e.target.value==='ip_ban'?'(IP address or hash)':'(email or account ID)'\n    $('#mtarget').placeholder=e.target.value==='ip_ban'?'1.2.3.4 or hash prefix':'member@example.com'\n  })\n  $('#modform').addEventListener('submit',async ev=>{\n    ev.preventDefault();const f=new FormData(ev.target)\n    state.busy=true;render()\n    try{\n      const out=await api('/api/owner/moderate',{method:'POST',body:JSON.stringify({\n        target:String(f.get('target')).trim(),type:String(f.get('type')),reason:String(f.get('reason')).trim(),\n        hours:Number(f.get('hours')||24),\n      })})\n      toast(out.enforced?'✓ Restriction is live and enforced on the server.':'Restriction saved.',out.enforced?'ok':'err')\n      await refresh()\n    }catch(e){toast(e.message,'err')}finally{state.busy=false;render()}\n  })\n}\n\nfunction beep(){\n  try{\n    const C=window.AudioContext||window.webkitAudioContext;if(!C)return\n    const c=new C(),o=c.createOscillator(),g=c.createGain()\n    o.connect(g);g.connect(c.destination);o.type='sine';o.frequency.value=660\n    g.gain.setValueAtTime(.001,c.currentTime);g.gain.exponentialRampToValueAtTime(.18,c.currentTime+.02)\n    g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.42)\n    o.start();o.stop(c.currentTime+.45);setTimeout(()=>c.close(),700)\n  }catch{}\n}\nfunction checkNew(list){\n  const fresh=list.filter(a=>!state.seen.has(a.id))\n  if(state.first){list.forEach(a=>state.seen.add(a.id));state.first=false;localStorage.setItem('fl3sh.seen',JSON.stringify([...state.seen]));return}\n  if(!fresh.length)return\n  fresh.forEach(a=>state.seen.add(a.id))\n  localStorage.setItem('fl3sh.seen',JSON.stringify([...state.seen]))\n  beep()\n  if(Notification.permission==='granted')new Notification('FL3SH Console — new AI alert',{body:fresh[0].title+' — '+fresh[0].detail.slice(0,90)})\n  toast('🔔 New AI alert: '+fresh[0].title)\n}\nasync function refresh(){\n  try{\n    const d=await api('/api/owner/dashboard')\n    state.data=d\n    checkNew(d.alerts.filter(a=>a.status==='pending'))\n    render()\n  }catch(e){if(!$('#app').innerHTML)toast(e.message,'err')}\n}\n\ndocument.addEventListener('click',async ev=>{\n  const b=ev.target.closest('[data-act]');if(!b)return\n  const act=b.dataset.act\n  if(act==='target'){const t=$('#mtarget');if(t){t.value=b.dataset.email;t.scrollIntoView({behavior:'smooth',block:'center'});t.focus()}return}\n  if(act==='verify'){\n    try{const out=await api('/api/owner/check?target='+encodeURIComponent(b.dataset.target))\n      toast(out.enforced?'✓ ENFORCED — '+out.moderation.type+' is active.':'Not enforced for that target.',out.enforced?'ok':'err')\n    }catch(e){toast(e.message,'err')}return}\n  if(act==='escalate-ip'){\n    state.busy=true;render()\n    try{\n      await api('/api/owner/moderate/'+b.dataset.id+'/update',{method:'POST',body:JSON.stringify({type:'ip_ban',reason:'Escalated to IP ban by owner',hours:24})})\n      toast('✓ IP ban is live on the server.','ok');await refresh()\n    }catch(e){toast(e.message,'err')}finally{state.busy=false;render()}return}\n  if(act==='update'){\n    const item=b.closest('.item')\n    const type=item.querySelector('.mtype').value\n    const reason=item.querySelector('.mreason').value.trim()\n    const hours=Number(item.querySelector('.mhours').value||24)\n    if(reason.length<5){toast('A reason of at least 5 characters is required.','err');return}\n    state.busy=true;render()\n    try{\n      await api('/api/owner/moderate/'+b.dataset.id+'/update',{method:'POST',body:JSON.stringify({type,reason,hours})})\n      toast('✓ Restriction changed and enforced.','ok');await refresh()\n    }catch(e){toast(e.message,'err')}finally{state.busy=false;render()}return}\n  state.busy=true;render()\n  try{\n    if(act==='decision')await api('/api/owner/alerts/'+b.dataset.id+'/decision',{method:'POST',body:JSON.stringify({decision:b.dataset.value})})\n    if(act==='revoke')await api('/api/owner/moderate/'+b.dataset.id+'/revoke',{method:'POST',body:'{}'})\n    toast('Done.','ok');await refresh()\n  }catch(e){toast(e.message,'err')}finally{state.busy=false;render()}\n})\n$('#refresh').addEventListener('click',()=>{refresh()})\n$('#logout').addEventListener('click',async()=>{try{await api('/api/owner/cookie-logout',{method:'POST',body:'{}'})}catch{}location.href='/console'})\n$('#notif').addEventListener('click',async()=>{\n  if(!('Notification' in window)){toast('Notifications are not supported here.','err');return}\n  const p=await Notification.requestPermission()\n  $('#notif').textContent=p==='granted'?'🔔 Alerts on':'🔔 Alerts off'\n  toast(p==='granted'?'Desktop alerts enabled.':'Desktop alerts not enabled.')\n})\nif('Notification' in window&&Notification.permission==='granted')$('#notif').textContent='🔔 Alerts on'\nrefresh()\nsetInterval(()=>{if(!state.busy)refresh()},15000)\n</script>\n</body>\n</html>\n";

export const CONSOLE_LOGIN_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n<meta name=\"robots\" content=\"noindex,nofollow\" />\n<title>FL3SH Console — Owner Access</title>\n<style>\n  :root { color-scheme: dark; --accent:#8b5cf6; --bg:#080810; }\n  * { box-sizing:border-box; }\n  body { margin:0; min-height:100vh; display:grid; place-items:center; padding:20px;\n    font-family:Inter,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif; color:#e9e9f2;\n    background:radial-gradient(1000px 600px at 50% -10%,rgba(139,92,246,.18),transparent 60%),var(--bg); }\n  .card { width:100%; max-width:400px; padding:30px 28px; border-radius:22px;\n    background:rgba(20,18,38,.78); border:1px solid rgba(139,92,246,.28);\n    box-shadow:0 24px 80px rgba(0,0,0,.55); backdrop-filter:blur(16px); }\n  .mark { width:58px; height:58px; margin:0 auto 16px; display:grid; place-items:center;\n    border-radius:18px; background:linear-gradient(145deg,#8b5cf6,#5b21b6); box-shadow:0 0 34px rgba(139,92,246,.5); }\n  h1 { margin:0; text-align:center; font-size:23px; letter-spacing:.3px;\n    background:linear-gradient(90deg,#c4b5fd,#fff); -webkit-background-clip:text; background-clip:text; color:transparent; }\n  .sub { margin:7px 0 24px; text-align:center; font-size:12px; color:#9d9ab5; }\n  label { display:block; font-size:11.5px; color:#b5b2c9; margin:13px 0 5px; }\n  input { width:100%; padding:11px 13px; border-radius:11px; color:#fff; font-size:13px;\n    background:rgba(255,255,255,.05); border:1px solid rgba(139,92,246,.25); outline:none; }\n  input:focus { border-color:var(--accent); box-shadow:0 0 0 3px rgba(139,92,246,.16); }\n  button { width:100%; margin-top:22px; padding:12px; border:0; border-radius:11px; cursor:pointer;\n    font-size:13px; font-weight:700; color:#fff; background:linear-gradient(135deg,#8b5cf6,#6d28d9); }\n  button:disabled { opacity:.55; cursor:default; }\n  .err { margin-top:12px; min-height:16px; text-align:center; font-size:12px; color:#f87171; }\n  .foot { margin-top:18px; text-align:center; font-size:10.5px; color:#6f6b88; }\n  .lock { display:inline-flex; align-items:center; gap:5px; }\n</style>\n</head>\n<body>\n  <div class=\"card\">\n    <div class=\"mark\">\n      <svg width=\"30\" height=\"30\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n        <rect x=\"4\" y=\"8\" width=\"16\" height=\"12\" rx=\"3\"/><path d=\"M12 8V5\"/><circle cx=\"12\" cy=\"3.5\" r=\"1.4\" fill=\"#fff\"/>\n        <circle cx=\"9\" cy=\"14\" r=\"1\"/><circle cx=\"15\" cy=\"14\" r=\"1\"/><path d=\"M9 17.5h6\"/>\n      </svg>\n    </div>\n    <h1>FL3SH Console</h1>\n    <p class=\"sub\"><span class=\"lock\">🔒 Private — owner access only</span></p>\n    <form id=\"f\">\n      <label for=\"e\">Owner email</label>\n      <input id=\"e\" type=\"email\" autocomplete=\"username\" value=\"caydenbonebrake@yahoo.com\" required />\n      <label for=\"p\">Password</label>\n      <input id=\"p\" type=\"password\" autocomplete=\"current-password\" placeholder=\"••••••••\" required />\n      <button id=\"b\" type=\"submit\">Unlock console</button>\n      <div class=\"err\" id=\"err\"></div>\n    </form>\n    <div class=\"foot\">MADE BY FL3SH · r00ster</div>\n  </div>\n<script>\n  document.getElementById('f').addEventListener('submit', async (ev) => {\n    ev.preventDefault()\n    const b = document.getElementById('b'), err = document.getElementById('err')\n    b.disabled = true; err.textContent = ''\n    try {\n      const res = await fetch('/api/owner/cookie-login', {\n        method: 'POST', credentials: 'same-origin',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ email: document.getElementById('e').value.trim(), password: document.getElementById('p').value }),\n      })\n      const data = await res.json().catch(() => ({}))\n      if (!res.ok) throw new Error(data.error || 'Could not sign in.')\n      location.reload()\n    } catch (e) {\n      err.textContent = e.message || 'Could not sign in.'\n      b.disabled = false\n    }\n  })\n</script>\n</body>\n</html>\n"
